export const boards={stage:{rows:5,cols:5},boss:{rows:5,cols:5},horde:{rows:6,cols:6},dojo:{rows:4,cols:3},goldrush:{rows:5,cols:5},other:{rows:5,cols:5}};
export const owner=(index,mode,cell)=>mode==='duo'?(cell?.player??1):1;
export const limit=draft=>draft.gameMode==='dojo'?5:draft.gameMode==='horde'?10:15;
export function cleanContext(value={}){const result={};const limits={stageType:['all','normal','boss'],boss:['Singer','Stamper','Road Bully','Drunkard','Fish Monster'],bossLevel:Array.from({length:100},(_,i)=>String(i+1)).concat('Endless'),dojoElement:['Fire','Water','Grass','Rock','Lightning'],dojoTier:['1','2','3','4','5','6','7']};for(const [key,allowed] of Object.entries(limits)){if(value[key]!==undefined){if(!allowed.includes(String(value[key])))throw Error('Invalid mode setup.');result[key]=String(value[key])}}for(const key of ['fromChapter','fromStage','toChapter','toStage','difficulty']){if(value[key]!==undefined&&value[key]!==''){const n=Number(value[key]);if(!Number.isInteger(n)||n<1||n>(key==='difficulty'?4:9999))throw Error(key==='difficulty'?'Horde difficulty must be 1–4.':'Enter valid positive setup numbers.');result[key]=n}}if(value.dojoStages!==undefined){if(!Array.isArray(value.dojoStages)||value.dojoStages.some(n=>!Number.isInteger(n)||n<1||n>10))throw Error('Invalid Dojo stages.');result.dojoStages=[...new Set(value.dojoStages)]}if(value.customName!==undefined)result.customName=String(value.customName).slice(0,80);return result}
export function cleanDraft(raw,known){const gameMode=raw?.gameMode||'horde',b=boards[gameMode];if(!raw||raw.schema!==1||!b||!['solo','duo'].includes(raw.mode)||raw.mode==='duo'&&gameMode!=='horde'||!Array.isArray(raw.cells)||raw.cells.length!==b.rows*b.cols)throw Error('Invalid draft format.');const seen={1:new Set(),2:new Set()},counts={1:0,2:0};const cells=raw.cells.map((cell,i)=>{if(cell===null)return null;if(!cell||!known.has(cell.key)||!Number.isInteger(cell.level)||cell.level<1||cell.level>7)throw Error('Invalid Tatari or level.');const p=raw.mode==='solo'?1:cell.player??(raw.ownershipVersion===2?1:i%6>=3?2:1);if(![1,2].includes(p))throw Error('Invalid player ownership.');const unit=known.get(cell.key);if(seen[p].has(unit.unitId)||++counts[p]>limit({gameMode}))throw Error('Formation limit exceeded or an evolution line is duplicated.');seen[p].add(unit.unitId);return {key:cell.key,level:cell.level,player:p}});const steps=raw.steps??[];if(!Array.isArray(steps)||steps.length>100)throw Error('Too many priority steps.');const zobos=Array.isArray(raw.zobos)?raw.zobos.filter((z,i,all)=>all.findIndex(v=>v.id===z.id)===i):raw.zobos??[],chips=raw.chips??[];if(!Array.isArray(zobos)||zobos.length>b.rows*b.cols*2||zobos.some(z=>!Number.isInteger(z.id)||z.id<1||!['green','grey'].includes(z.zone)||!Number.isInteger(z.index)||z.index<0||z.index>=cells.length||z.zone==='green'&&cells[z.index]))throw Error('Invalid Zobo placement.');if(!Array.isArray(chips)||chips.length>6||chips.some(c=>!Number.isInteger(c.id)||c.id<1||c.id>49||![1,2].includes(c.player)))throw Error('Invalid chips.');for(const player of [1,2])if(chips.filter(c=>c.player===player).length>3)throw Error('Select up to 3 chips per player.');return {schema:1,ownershipVersion:2,zobos:zobos.map(z=>({id:z.id,zone:z.zone,index:z.index})),chips:chips.map(c=>({id:c.id,player:c.player})),fullField:!!raw.fullField,shareTheme:raw.shareTheme==='dark'?'dark':'light',shareAuthor:String(raw.shareAuthor??'').slice(0,80),shareNotes:String(raw.shareNotes??'').slice(0,500),context:cleanContext(raw.context),gameMode,mode:raw.mode,name:String(raw.name??'').slice(0,80),cells,steps:steps.map(s=>{if(!s||![1,2].includes(s.player)||!Array.isArray(s.keys)||!s.keys.length||s.keys.length>10||s.keys.some(k=>!known.has(k))||!Number.isInteger(s.target)||s.target<0||s.target>7)throw Error('Invalid priority step.');return {player:s.player,keys:[...new Set(s.keys)],target:s.target,note:String(s.note??'').slice(0,180)}})}}
export function canPlace(draft,index,key,known,from=null,assignedPlayer=1){if(!Number.isInteger(index)||index<0||index>=draft.cells.length)return 'Choose a valid board cell.';const entry=known.get(key);if(!entry)return 'Choose a recorded Tatari.';const p=draft.mode==='duo'?(from===null?assignedPlayer:owner(from,draft.mode,draft.cells[from])):1;if(![1,2].includes(p))return 'Choose P1 or P2.';const ms=draft.cells.filter((c,i)=>c&&owner(i,draft.mode,c)===p&&i!==index&&i!==from);if(ms.some(c=>known.get(c.key).unitId===entry.unitId))return 'That evolution line is already on this player’s board.';if(ms.length>=limit(draft))return 'This player has reached the formation limit.';return null}
